head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL16201";
scwin.insQuest = undefined;
scwin.Quest = null;

///////// 2. 초기화 영역 /////////
// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — quesCnt

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb1", fn: function () { return String(dma_poll.get("questStrtDd")) + " ~ " + String(dma_poll.get("questEndDd")); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

// [A] 초기 목록 미해결 — jldfil16201: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.insQuest =new Quest((String(((dma_pageContext.get("quesCnt") ?? "")) == null ? '' : ((dma_pageContext.get("quesCnt") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("quesCnt") ?? "")) == null ? '' : ((dma_pageContext.get("quesCnt") ?? ""))))); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil16201' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.Quest = Quest;
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil16201.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_RegisterPoll_onclick
 * @description 「수정」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_RegisterPoll_onclick = async function(e){
    try {
        await scwin.registerPoll('' + dma_poll.get("questNo") + '',1)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil16201.btn_RegisterPoll_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_RegisterPoll
 * @description Register Poll 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_RegisterPoll = async function (action) {
    const sbmOptions = {
        id: "tx_fn_RegisterPoll",
        method: "post",
        action: action ?? "/support/poll.do",
        ref: "dma_RegisterPollReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
function Quest(_quesCnt) {
    this.quesCnt = _quesCnt;
    this.quesObj = [];
}

/**
 * @method
 * @name Ques
 * @description Ques 처리
 * @param {*} _quesNo _quesNo
 * @param {String} _quesTpCd _quesTpCd
 * @param {*} _ansChoicCnt _ansChoicCnt
 * @param {*} _upQuesNo _upQuesNo
 * @param {*} _respnsMandtryNoContn _respnsMandtryNoContn
 * @param {String} _respnsMandtryYn _respnsMandtryYn
 * @returns {void}
 * @hidden N
 */
scwin.Ques = function (_quesNo, _quesTpCd, _ansChoicCnt, _upQuesNo, _respnsMandtryNoContn, _respnsMandtryYn) {
    this.quesNo = _quesNo;
    this.quesTpCd = _quesTpCd;
    this.ansChoicCnt = _ansChoicCnt;
    this.upQuesNo = _upQuesNo;
    this.respnsMandtryNoContn = _respnsMandtryNoContn;
    this.respnsMandtryYn = _respnsMandtryYn;
};

/**
 * @method
 * @name registerPoll
 * @description register Poll 처리
 * @param {*} _questNo _questNo
 * @param {String} _questProgStatCd _questProgStatCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.registerPoll = async function (_questNo, _questProgStatCd) {
    $c.util.getComponent('dma_RegisterPollReq').set('questNo', _questNo);
    $c.util.getComponent('dma_RegisterPollReq').set('questProgStatCd', _questProgStatCd);
    $c.util.getComponent('dma_RegisterPollReq').set('method', 'registerPollForm');
    const nr = await scwin.tx_fn_RegisterPoll('poll.do');
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/ui/jsp/JLDFIL16200.xml", { "questNo": _questNo, "questProgStatCd": _questProgStatCd, "method": 'registerPollForm' });
    }
};
